    restore('ticketChannel',setTicketChannel);restore('ticketCategory',setTicketCategory);restore('supportRole',setSupportRole);restore('ticketText',setTicketText);
    restore('ticketTitle',setTicketTitle);restore('ticketColor',setTicketColor);restore('ticketFooter',setTicketFooter);restore('ticketImageUrl',setTicketImageUrl);restore('ticketThumbUrl',setTicketThumbUrl);
    restore('verifyChannel',setVerifyChannel);restore('verifyRole',setVerifyRole);restore('verifyText',setVerifyText);restore('verifyTitle',setVerifyTitle);restore('verifyColor',setVerifyColor);restore('verifyFooter',setVerifyFooter);restore('verifyImageUrl',setVerifyImageUrl);restore('verifyThumbUrl',setVerifyThumbUrl);
    restore('embedChannel',setEmbedChannel);if(typeof d.embedEveryone==='boolean')setEmbedEveryone(d.embedEveryone);restore('embedRole',setEmbedRole);restore('title',setTitle);restore('description',setDescription);restore('embedContent',setEmbedContent);restore('embedFooter',setEmbedFooter);restore('embedAuthor',setEmbedAuthor);restore('embedColor',setEmbedColor);restore('embedImageUrl',setEmbedImageUrl);restore('embedThumbUrl',setEmbedThumbUrl);
    restore('giveawayChannel',setGiveawayChannel);restore('giveawayPrize',setGiveawayPrize);restore('giveawayTitle',setGiveawayTitle);restore('giveawayDescription',setGiveawayDescription);restore('giveawayColor',setGiveawayColor);restore('giveawayFooter',setGiveawayFooter);restore('giveawayImageUrl',setGiveawayImageUrl);restore('giveawayThumbUrl',setGiveawayThumbUrl);
    if(Array.isArray(d.ticketOptions))setTicketOptions(d.ticketOptions as TicketOption[]);
